def init_velocity():
    """
    Initialize the Velocity client.

    This function prompts the user to enter their Velocity username and password,
    stores the credentials securely using the keyring module, and initializes the
    Velocity client with the provided credentials.

    The Velocity client is configured to connect to the Velocity server at
    'https://velocityoulu.ou.nsn-rdnet.net/' and logs are saved in the current
    working directory.

    Raises:
        Exception: If there is an error during the initialization of the Velocity client.
    """
    server = input("Select Velocity server (Oulu/Polaris/Test): ")
    if server.lower() == "oulu" or server.lower() == "o":
        velocity_server = "https://velocityoulu.ou.nsn-rdnet.net/"
    elif server.lower() == "polaris" or server.lower() == "p":
        velocity_server = "https://velocity.linnanmaa.dyn.nesc.nokia.net/"
    elif server.lower() == "test" or server.lower() == "t":
        velocity_server = "https://10.35.195.9/"
    else:
        print("Invalid input. Please try again.")
        return None

    creds = input("Use existing credentials? (y/n): ")
    if creds.lower() == "y":
        user = keyring.get_credential("velocity", None)
        if user is None:
            print("No saved credentials.")
            username, password = ask_password()
        else:
            username = user.username
            password = user.password
    elif creds.lower() == "n":
        username, password = ask_password()
    else:
        print("Invalid input. Please try again.")
        return None

    print("Initializing Velocity client...")
    client = velocityclient.VelocityRestClient(
        server=velocity_server,
        username=username,
        password=password,
        console_log=False,
        log_dir=os.getcwd())
    print(f"Velocity client initialized at {velocity_server}")
    print(f"Logs are saved in {os.getcwd()}.")

    return client


def ask_password():
    username = input("Enter your Velocity username: ")
    password = getpass.getpass("Enter your Velocity password: ")

    keyring.set_password("velocity", username, password)

    return username, password


def main():
    warnings.filterwarnings("ignore", category=SyntaxWarning)
    cli_interface()


if __name__ == '__main__':
    main()
